     *
     */
    public static List<List<Object>> listSplit(List<Object> s, int step) {
        List<List<Object>> retList = new ArrayList<>();
        int index = 0;
        for (int i = 0; i < step; i++) {
            retList.add(new ArrayList<>());
        }

        for (Object o : s) {
            retList.get(index).add(o);
            index += 1;
            if (index >= step) {
                index = 0;
            }
        }

        return retList;
    }
}

