    /**
     * * Write a function to compute binomial probability for the given number.
     *
     */
    public static Double binomialProbability(int n, int k, Double p) {
        double sum = 1;
        for (int i = 0; i < k; i++) {
            sum = sum * (n - i) / (i + 1);
        }
        return sum * Math.pow(p, k) * Math.pow(1 - p, n - k);
    }
}

