     *
     */
    public static int floorMax(int a, int b, int n) {
        int diff = a ^ b ^ n;
        int count = 0;
        while (diff > 0) {
            diff = diff & (diff - 1);
            count++;
        }
        return count == 1 ? n : count;
    }
}

