    int start = 0;
    int end = 0;
    for (int i = 0; i < text.length(); i++){
      if (text.charAt(i) == ' '){
        end = end + 1;
      } else {
        if (end - start > 2){
          sb.append('-');
        } else {
          if (end - start > 0){
